//! Types shared between Rust and the frontend. TypeScript bindings are generated by
//! `ts-rs` into `src/lib/bindings/` when running `cargo test`.

use serde::{Deserialize, Serialize};
use ts_rs::TS;

#[derive(Serialize, Deserialize, TS, Clone, Copy, PartialEq, Eq, Debug, Hash)]
#[serde(rename_all = "lowercase")]
#[ts(export)]
pub enum Kind {
    Text,
    Rich,
    Link,
    Image,
    File,
    Color,
    Code,
}

impl Kind {
    pub fn as_str(self) -> &'static str {
        match self {
            Kind::Text => "text",
            Kind::Rich => "rich",
            Kind::Link => "link",
            Kind::Image => "image",
            Kind::File => "file",
            Kind::Color => "color",
            Kind::Code => "code",
        }
    }
    pub fn parse(s: &str) -> Option<Kind> {
        Some(match s {
            "text" => Kind::Text,
            "rich" => Kind::Rich,
            "link" => Kind::Link,
            "image" => Kind::Image,
            "file" => Kind::File,
            "color" => Kind::Color,
            "code" => Kind::Code,
            _ => return None,
        })
    }
}

/// Application that owned the clipboard at copy time.
#[derive(Serialize, Deserialize, TS, Clone, Debug, PartialEq)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct SourceApp {
    pub bundle_id: String,
    pub name: String,
    pub color: Option<String>,
    pub icon_path: Option<String>,
}

/// List/card representation of an item (no heavy blobs, text truncated).
#[derive(Serialize, Deserialize, TS, Clone, Debug)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct Item {
    pub id: i64,
    pub kind: Kind,
    pub preview: String,
    pub char_count: i64,
    pub has_rich: bool,
    pub file_paths: Vec<String>,
    pub image_path: Option<String>,
    pub thumb_path: Option<String>,
    pub width: Option<i64>,
    pub height: Option<i64>,
    pub byte_size: i64,
    pub source_bundle_id: Option<String>,
    pub source_app_name: Option<String>,
    pub source_color: Option<String>,
    pub source_icon_path: Option<String>,
    pub link_title: Option<String>,
    pub link_favicon_path: Option<String>,
    pub language: Option<String>,
    pub pinned: bool,
    pub space_id: Option<i64>,
    pub use_count: i64,
    pub created_at: i64,
    pub last_used_at: i64,
    pub expires_at: Option<i64>,
    pub tag_ids: Vec<i64>,
}

#[derive(Serialize, Deserialize, TS, Clone, Debug)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct ItemDetail {
    pub item: Item,
    pub text: Option<String>,
    pub html: Option<String>,
    pub ocr_text: Option<String>,
}

#[derive(Serialize, Deserialize, TS, Clone, Copy, Debug, Default, PartialEq, Eq)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub enum Sort {
    #[default]
    Recent,
    MostUsed,
    PinnedFirst,
}

#[derive(Serialize, Deserialize, TS, Clone, Debug, Default)]
#[serde(rename_all = "camelCase", default)]
#[ts(export)]
pub struct ItemQuery {
    /// Free text (already stripped of `key:value` filters).
    pub text: String,
    pub kinds: Vec<Kind>,
    /// Exact bundle ids (app filter bar).
    pub apps: Vec<String>,
    /// Case-insensitive substrings of the app name or bundle id (`app:safari`).
    pub app_names: Vec<String>,
    /// Tag names, all must match (`tag:work`).
    pub tags: Vec<String>,
    pub space_id: Option<i64>,
    /// Space names (`space:snippets`), resolved case-insensitively.
    pub space_names: Vec<String>,
    pub pinned: Option<bool>,
    /// Only items used/copied at or after this unix-ms timestamp.
    pub since: Option<i64>,
    pub sort: Sort,
    pub offset: i64,
    pub limit: i64,
}

#[derive(Serialize, Deserialize, TS, Clone, Debug)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct Space {
    pub id: i64,
    pub name: String,
    pub color: Option<String>,
    pub icon: Option<String>,
    pub position: i64,
    pub count: i64,
}

#[derive(Serialize, Deserialize, TS, Clone, Debug)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct Tag {
    pub id: i64,
    pub name: String,
    pub color: Option<String>,
    pub count: i64,
}

#[derive(Serialize, Deserialize, TS, Clone, Debug)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct SourceAppInfo {
    pub bundle_id: String,
    pub name: String,
    pub color: Option<String>,
    pub icon_path: Option<String>,
    pub count: i64,
    pub last_seen: i64,
}

#[derive(Serialize, Deserialize, TS, Clone, Debug)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct ExcludedApp {
    pub bundle_id: String,
    pub name: Option<String>,
}

#[derive(Serialize, Deserialize, TS, Clone, Debug)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct Counts {
    pub all: i64,
    pub pinned: i64,
}
